function pathSeg(el,opt){opt=opt||{};el.classList.add("path-seg");PK.forEach(k=>{const p=PATHS[k];const b=H("button",{class:`tg num ${k}`,title:`Caminho ${p.tag} · ${p.n}`},el,p.tag);b.addEventListener("click",e=>{e.stopPropagation();setPath(k,el)})});const nm=opt.name===false?null:H("span",{class:"pname"},el,"");onPath(k=>{el.querySelectorAll(".tg").forEach(b=>b.classList.toggle("on",b.classList.contains(k)));if(nm){const p=PATHS[k];nm.innerHTML=`<b style="color:${p.col}">${p.n}</b> · ${p.T}`}})}

